"""No watermarks or AI/Muse branding in shipped code or docs."""

import pathlib

ROOT = pathlib.Path(__file__).resolve().parent.parent

BANNED = ["Muse", "Claude", "Anthropic", "AI-generated",
          "generated by AI", "powered by Muse"]

# RESEARCH.md is a research log and may name trending repos / papers.
ALLOWED = {"docs/RESEARCH.md"}


def test_no_branding():
    hits = []
    for path in ROOT.rglob("*"):
        if not path.is_file():
            continue
        rel = str(path.relative_to(ROOT))
        if rel in ALLOWED or rel == "tests/test_branding.py":
            continue
        if path.suffix not in {".py", ".md", ".txt", ".toml", ".yml", ".json"}:
            continue
        if ".venv" in rel or "__pycache__" in rel:
            continue
        text = path.read_text(errors="ignore")
        for banned in BANNED:
            if banned in text:
                hits.append((rel, banned))
    assert not hits, hits
